import{_ as t,o as s,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/troubleshooting.md","filePath":"user-guide/troubleshooting.md","lastUpdated":1787586465000}'),n={name:"user-guide/troubleshooting.md"};function r(a,e,l,d,c,g){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Encountering issues while using Lertaro? Follow these systematic steps to diagnose and resolve common situations.</p><h2 id="_1-global-hotkeys-not-responding" tabindex="-1">1. Global Hotkeys Not Responding <a class="header-anchor" href="#_1-global-hotkeys-not-responding" aria-label="Permalink to &quot;1. Global Hotkeys Not Responding&quot;">​</a></h2><ul><li><strong>Verify Background Service Status</strong>: Go to <a href="./settings/service-status.html"><strong>Settings → Service Status</strong></a> and verify that <code>Lertaro.Service</code> is running. While general hotkeys are handled by the App, the elevated hook process depends on the background service.</li><li><strong>Administrative Privilege Isolation (UIPI)</strong>: If the active foreground window is elevated (e.g. Administrator Terminal or Task Manager), Windows UIPI prevents standard-user processes from intercepting hotkeys. Lertaro automatically elevates its keyboard hook process via the service; ensure the service is running.</li><li><strong>Check Process Blacklist</strong>: In <a href="./settings/hotkeys-page.html#process-blacklist"><strong>Settings → Hotkeys</strong></a>, ensure the active application is not listed in the Process Blacklist. Blacklisted apps cause Lertaro to bypass global hotkeys intentionally.</li><li><strong>Fullscreen App Bypass</strong>: When an application is running in exclusive fullscreen mode (e.g. 3D games or video players), Lertaro suppresses hotkeys by default. Enable <strong>Respond when focused on full-screen applications</strong> under <strong>Settings → Hotkeys</strong> if you wish to override this behavior.</li></ul><h2 id="_2-search-results-stale-or-incomplete" tabindex="-1">2. Search Results Stale or Incomplete <a class="header-anchor" href="#_2-search-results-stale-or-incomplete" aria-label="Permalink to &quot;2. Search Results Stale or Incomplete&quot;">​</a></h2><ul><li><strong>Local NTFS / ReFS Drives</strong>: Updated in real time with near-zero latency by monitoring the filesystem&#39;s USN Change Journal.</li><li><strong>FAT32 / exFAT Drives</strong>: Tracked continuously via filesystem change events.</li><li><strong>Manual Reindex</strong>: If an unexpected crash or sudden power cut caused index discrepancies, go to <a href="./settings/index-drives.html"><strong>Settings → Indexing → Local Drives</strong></a> and click <strong>Rebuild Index</strong> on the affected drive.</li></ul><h2 id="_3-network-drives-not-refreshing" tabindex="-1">3. Network Drives Not Refreshing <a class="header-anchor" href="#_3-network-drives-not-refreshing" aria-label="Permalink to &quot;3. Network Drives Not Refreshing&quot;">​</a></h2><ul><li><strong>Scheduled Rescan</strong>: Network shares (SMB / NAS) lack local USN journals and rely on scheduled polling.</li><li><strong>Check Refresh Mode</strong>: In <a href="./settings/index-drives.html#network-drives"><strong>Settings → Indexing → Network Drives</strong></a>, check if the refresh mode is set to &quot;Manual&quot;. If so, switch to a periodic schedule or click &quot;Rebuild Index&quot;.</li><li><strong>Symlink Loop Protection</strong>: Lertaro includes a built-in cycle detection engine to prevent infinite loops caused by recursive symbolic links on NAS shares.</li></ul><h2 id="_4-specific-files-or-folders-missing" tabindex="-1">4. Specific Files or Folders Missing <a class="header-anchor" href="#_4-specific-files-or-folders-missing" aria-label="Permalink to &quot;4. Specific Files or Folders Missing&quot;">​</a></h2><ul><li><strong>Review Exclusion Rules</strong>: Go to <a href="./settings/index-drives.html#exclusion-rules"><strong>Settings → Indexing → Exclusions</strong></a> and verify that the path is not inadvertently matched by exact path, glob, or regex patterns.</li><li><strong>Verify Drive Status</strong>: In <a href="./settings/index-drives.html"><strong>Settings → Indexing → Local Drives</strong></a>, confirm that the drive or mount point containing the file is marked as enabled.</li></ul><h2 id="_5-ime-candidate-window-not-appearing-in-inline-window" tabindex="-1">5. IME Candidate Window Not Appearing in Inline Window <a class="header-anchor" href="#_5-ime-candidate-window-not-appearing-in-inline-window" aria-label="Permalink to &quot;5. IME Candidate Window Not Appearing in Inline Window&quot;">​</a></h2><ul><li><strong>Non-Focus Design</strong>: The <a href="./getting-started.html#3-three-window-modes">Inline Window</a> intentionally avoids stealing real keyboard focus from the host application so it can dismiss cleanly without UI flicker. Because IME candidate popups require true window focus, they may not render in inline mode.</li><li><strong>Recommended Solutions</strong>: <ol><li><strong>Direct Pinyin Typing</strong>: Lertaro features an embedded pinyin alias engine; type pinyin letters directly to fuzzy-match Chinese filenames without opening an IME popup (see <a href="./search-syntax.html#8-multilingual--pinyin-aliases"><strong>Search Syntax</strong></a>).</li><li><strong>Switch to Quick Window</strong>: Double-tap <code>Ctrl</code> to open the fully focused Quick Window, where all input methods work normally.</li></ol></li></ul><h2 id="_6-inspecting-logs-submitting-issues" tabindex="-1">6. Inspecting Logs &amp; Submitting Issues <a class="header-anchor" href="#_6-inspecting-logs-submitting-issues" aria-label="Permalink to &quot;6. Inspecting Logs &amp; Submitting Issues&quot;">​</a></h2><p>If the problem persists, visit <a href="./settings/service-status.html"><strong>Settings → Service Status</strong></a> to inspect live logs:</p><ul><li><strong>Service Logs</strong>: Records background indexing, USN journals, network scans, and IPC communication.</li><li><strong>App Logs</strong>: Records foreground UI rendering, plugin lifecycles, and configuration updates.</li><li><strong>Hook Logs</strong>: Records global keyboard hook and mouse gesture event streams.</li></ul><p>Use the search bar to filter keywords or sort by severity (Info / Warn / Error) to locate stack traces before attaching logs to a GitHub issue.</p>',16)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
